const D = { scale:1, energy:.6, hue:190, speed:1, density:.5, sinuous:1, taper:.55, mantle:1, limbs:8, x:.5, y:.44, seed:0, pose:'auto', style:'biolum', act:'flow' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const s = u * 0.0017 * P.scale;
const bt = K.beat * P.speed;
const am = .82 + .22*Math.sin(K.t*.27 + fr(6)*6);
const eAmp = P.energy*(.5 + .6*K.intensity)*am;
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + A.bass*.7);
S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;

const nT = Math.max(4, Math.min(10, Math.round(P.limbs)));
const st = ['biolum','xray','ink','iridescent','wire'].includes(P.style) ? P.style : 'biolum';
const H = ((P.hue%360)+360)%360;
const mantleR = 66*P.mantle;

// seed/count-dependent tentacle rig
if (S.seedUsed !== P.seed || S.nUsed !== nT || !S.tent){
  S.seedUsed = P.seed; S.nUsed = nT; S.tent = [];
  for (let i=0;i<nT;i++){
    const f = nT>1 ? i/(nT-1) : .5;
    const rootAng = Math.PI*(0.13 + 0.74*f);
    S.tent.push({
      rx: Math.cos(rootAng)*mantleR*0.9,
      ry: Math.sin(rootAng)*mantleR*0.5 + mantleR*0.32,
      hang: Math.PI/2 + (rootAng - Math.PI/2)*0.92,
      dir: (fr(i+3) < .5 ? -1 : 1),
      ph: fr(i+11)*6.283,
      freq: 2.2 + fr(i+21)*1.4,
      chrom: [fr(i+31), fr(i+41), fr(i+51), fr(i+61)]
    });
  }
}
// glow sprite (built once)
if (!S.glow){
  const g = createGraphics(64,64); const c = g.drawingContext;
  const grd = c.createRadialGradient(32,32,0,32,32,32);
  grd.addColorStop(0,'rgba(255,255,255,1)'); grd.addColorStop(.35,'rgba(255,255,255,.45)'); grd.addColorStop(1,'rgba(255,255,255,0)');
  c.fillStyle = grd; c.fillRect(0,0,64,64); S.glow = g;
}

const ACTS = {
  flow:  ['groove','drift','groove','spin','groove','drift','jet','spin'],
  calm:  ['drift','groove','drift','drift','groove','drift','drift','groove'],
  frenzy:['spin','groove','jet','spin','groove','jet','spin','groove'] };
let pose = P.pose;
if (pose==='auto') pose = (ACTS[P.act]||ACTS.flow)[((K.section%8)+8)%8];

// ── pose → whole-body params ────────────────────────────
let spinAng=0, tilt=0, dyP=0, squash=1, waveBoost=1, mantlePulse=0, streamBias=0;
if (pose==='drift'){
  dyP = Math.sin(K.t*.7)*12; tilt = Math.sin(K.t*.5)*.09;
  waveBoost = 1; mantlePulse = K.swell*.05*eAmp;
} else if (pose==='groove'){
  dyP = -kick*9 + Math.sin(bt*Math.PI)*5*eAmp; tilt = Math.sin(bt*Math.PI/2)*.07*eAmp;
  waveBoost = 1.25; mantlePulse = kick*.13*eAmp;
} else if (pose==='spin'){
  spinAng = bt*Math.PI*0.5*eAmp + K.t*.3; dyP = Math.sin(K.t*1.1)*9;
  waveBoost = .8; streamBias = .35; mantlePulse = K.swell*.04;
} else { // jet
  const je = kick;
  dyP = -je*48*eAmp + Math.sin(K.t*.8)*6; squash = 1 - je*.17*eAmp;
  tilt = Math.sin(K.t*.3)*.05; streamBias = .5 + .5*je; mantlePulse = je*.15*eAmp;
  waveBoost = 1;
}
// slow drift — evolution guarantee
dyP += Math.sin(K.t*.41 + fr(2)*6)*7;
tilt += Math.sin(K.t*.19 + fr(8)*6)*.03;
spinAng += Math.sin(K.t*.13)*.04;

const ax = P.x*width, ay = P.y*height;
const pump = 1 + mantlePulse + S.rms*.2*P.energy;
const hueDrift = (H + Math.sin(K.t*.13)*10 + 360)%360;

function stamp(x,y,r,h,sa,br,a){ blendMode(ADD); noStroke(); tint(h,sa,br,a); image(S.glow, x-r, y-r, r*2, r*2); noTint(); blendMode(BLEND); }

push();
translate(ax, ay + dyP*s);
rotate(spinAng*0 + tilt);          // spinAng applied to tentacle field via param, not whole flip, keeps eyes readable
scale(s*pump, s*pump*squash);

// ── build + draw tentacles ──────────────────────────────
const segLenBase = 15.5, segW0 = 12;
const tips = [];
for (let i=0;i<nT;i++){
  const p = S.tent[i];
  const activeIdx = ((Math.floor(bt)%nT)+nT)%nT;
  const active = activeIdx===i ? K.pulse : 0;
  const n = 11;
  let x = p.rx, y = p.ry, ang = p.hang + spinAng*(0.4+0.6*(i/(nT-1)||0));
  const baseCurl = p.dir*(0.09 + 0.05*Math.sin(K.t*.5 + p.ph))*(1-streamBias*0.8);
  const actCurl = p.dir*active*0.85*eAmp;
  const L=[], R=[], C=[];
  for (let j=0;j<=n;j++){
    const tt=j/n;
    const segLen = segLenBase*(1 - tt*0.32*P.taper);
    x += Math.cos(ang)*segLen; y += Math.sin(ang)*segLen;
    const w = Math.sin(tt*p.freq - bt*Math.PI*1.3 + p.ph)*(0.20*P.sinuous)*(0.3+tt)*(0.55+.9*eAmp)*waveBoost;
    ang += baseCurl + actCurl*Math.sin(tt*Math.PI) + w;
    const wd = segW0*(1 - tt*0.7*P.taper)*(0.9);
    const px=Math.cos(ang+Math.PI/2), py=Math.sin(ang+Math.PI/2);
    L.push([x+px*wd, y+py*wd]); R.push([x-px*wd, y-py*wd]); C.push([x,y,wd,tt]);
  }
  tips.push([x,y,i,active]);
  const th = (hueDrift + i/nT*40 + Math.sin(K.t*.3+i)*14 + 360)%360;

  if (st==='wire'){
    stroke(th, 60, 100, 70); strokeWeight(1.2); noFill();
    beginShape(); for(const q of L) vertex(q[0],q[1]); endShape();
    beginShape(); for(const q of R) vertex(q[0],q[1]); endShape();
    for(let j=0;j<=n;j+=2){ line(L[j][0],L[j][1],R[j][0],R[j][1]); }
  } else if (st==='iridescent'){
    noStroke();
    for(let j=0;j<n;j++){ const bh=(th + j*12 + K.t*18)%360;
      fill(bh, 55, 95, 88);
      beginShape(); vertex(L[j][0],L[j][1]); vertex(R[j][0],R[j][1]); vertex(R[j+1][0],R[j+1][1]); vertex(L[j+1][0],L[j+1][1]); endShape(CLOSE); }
  } else if (st==='ink'){
    noStroke(); fill(220, 18, 16, 88);
    beginShape(); for(const q of L) curveVertex(q[0],q[1]); for(let j=R.length-1;j>=0;j--) curveVertex(R[j][0],R[j][1]); endShape(CLOSE);
    stroke(220,20,6,55); strokeWeight(1); noFill();
    beginShape(); for(let j=0;j<C.length;j+=2) curveVertex(C[j][0],C[j][1]); endShape();
  } else if (st==='xray'){
    noStroke(); fill(th, 45, 60, 22);
    beginShape(); for(const q of L) curveVertex(q[0],q[1]); for(let j=R.length-1;j>=0;j--) curveVertex(R[j][0],R[j][1]); endShape(CLOSE);
    stroke(th, 30, 100, 70); strokeWeight(1); noFill();
    beginShape(); for(const q of C) vertex(q[0],q[1]); endShape();
    noStroke(); fill((th+40)%360, 20, 100, 60);
    for(let j=1;j<C.length;j+=2){ const su=1.6+2.2*(1-C[j][3]); circle(C[j][0], C[j][1], su); }
  } else { // biolum
    noStroke();
    for(let lay=0;lay<2;lay++){ fill(th, 70-lay*30, 55+lay*40, lay?22:64);
      beginShape(); for(const q of L) curveVertex(q[0],q[1]); for(let j=R.length-1;j>=0;j--) curveVertex(R[j][0],R[j][1]); endShape(CLOSE); }
    for(let j=1;j<C.length;j+=2){ const gl=6+active*22; stamp(C[j][0],C[j][1], (2.5+2.5*(1-C[j][3]))+gl*0.12, (th+30)%360, 45, 100, 26+active*45+C[j][3]*10); }
  }
}

// ── mantle (head) ───────────────────────────────────────
const mh = (hueDrift+360)%360;
if (st==='biolum'){
  stamp(0, -mantleR*0.15, mantleR*1.7, mh, 55, 100, 30 + kick*22);
  noStroke();
  for(let lay=0;lay<3;lay++){ fill(mh, 78-lay*24, 42+lay*22, lay?26:78);
    ellipse(0, -mantleR*0.15, (mantleR*2-lay*mantleR*.5), (mantleR*2.2-lay*mantleR*.5)); }
  // chromatophore dots pulsing
  blendMode(ADD); noStroke();
  for(let i=0;i<14;i++){ const a=fr(i+70)*6.283, rr=fr(i+80)*mantleR*.85;
    const tw=.4+.6*Math.abs(Math.sin(K.t*1.4 + i + fr(i+90)*6));
    fill((mh+50+i*6)%360, 40, 100, 12 + tw*(14+kick*18));
    circle(Math.cos(a)*rr, -mantleR*0.15 + Math.sin(a)*rr*.9, 3+tw*4); }
  blendMode(BLEND);
} else if (st==='wire'){
  stroke(mh,55,100,75); strokeWeight(1.2); noFill();
  ellipse(0,-mantleR*.15, mantleR*2, mantleR*2.2);
  for(let k=1;k<4;k++) ellipse(0,-mantleR*.15, mantleR*2*(1-k*.24), mantleR*2.2);
  for(let k=-2;k<=2;k++) ellipse(0,-mantleR*.15, mantleR*2, mantleR*2.2*Math.abs(k/3));
} else if (st==='ink'){
  noStroke(); fill(220,20,14,92);
  beginShape();
  for(let a=0;a<=24;a++){ const th2=Math.PI*(a/24)*2; const rr=1+(fr(a+120)-.5)*.12;
    curveVertex(Math.cos(th2)*mantleR*rr, -mantleR*.15+Math.sin(th2)*mantleR*1.1*rr); }
  endShape(CLOSE);
  fill(220,10,30,40); ellipse(-mantleR*.3,-mantleR*.5, mantleR*.7, mantleR*.5);
} else if (st==='xray'){
  noStroke(); fill(mh,40,70,20); ellipse(0,-mantleR*.15, mantleR*2, mantleR*2.2);
  stroke(mh,25,100,75); strokeWeight(1.1); noFill(); ellipse(0,-mantleR*.15, mantleR*2, mantleR*2.2);
  // inner funnel + gill arcs
  ellipse(0,-mantleR*.15, mantleR*.9, mantleR*1.3);
  for(let k=0;k<3;k++) arc(0,-mantleR*.1, mantleR*(1.3-k*.3), mantleR*(1.5-k*.3), Math.PI*.15, Math.PI*.85);
} else { // iridescent
  noStroke();
  for(let k=6;k>=0;k--){ fill((mh+k*22+K.t*15)%360, 55, 95, k===0?95:70);
    ellipse(0,-mantleR*.15, mantleR*2*(k/6), mantleR*2.2*(k/6)); }
}

// eyes (horizontal-slit pupil) — glowing
const ey = -mantleR*0.28, ex = mantleR*0.42, blink = ((K.t*.19+fr(9))%1)<.045;
for (let e=0;e<2;e++){ const sgn = e?1:-1;
  if (st==='wire' || st==='xray'){ stroke(mh,20,100,85); strokeWeight(1.2); noFill(); ellipse(sgn*ex, ey, mantleR*.5, mantleR*.42);
    if(!blink){ line(sgn*ex-mantleR*.16, ey, sgn*ex+mantleR*.16, ey); } }
  else {
    if (st==='biolum'){ stamp(sgn*ex, ey, mantleR*.5, 52, 30, 100, 40+kick*20); }
    noStroke(); fill(50,25,100,st==='ink'?90:96); ellipse(sgn*ex, ey, mantleR*.52, mantleR*.44);
    if (!blink){ noStroke(); fill(0,0,6,95); rectMode(CENTER); rect(sgn*ex, ey, mantleR*.34, mantleR*.11, mantleR*.05);
      fill(0,0,100,80); circle(sgn*ex - sgn*mantleR*.05, ey-mantleR*.03, mantleR*.05); }
    else { stroke(0,0,10,90); strokeWeight(2); line(sgn*ex-mantleR*.18, ey, sgn*ex+mantleR*.18, ey); noStroke(); }
  }
}

pop();

// tip glow flares (biolum) drawn in screen space at scaled positions
if (st==='biolum'){
  for(const tp of tips){ const gx=ax+tp[0]*s*pump, gy=ay+dyP*s+tp[1]*s*pump*squash;
    blendMode(ADD); noStroke(); tint((hueDrift+40)%360, 40, 100, 30 + tp[3]*50 + S.tre*40);
    const r=(7+tp[3]*16)*s; image(S.glow, gx-r, gy-r, r*2, r*2); noTint(); blendMode(BLEND);
  }
}
blendMode(BLEND);
